    "_Follow %n person?_::_Follow %n people?_" : ["A bheil thu airson leantainn air %n neach?","A bheil thu airson leantainn air %n neach?","A bheil thu airson leantainn air %n daoine?","A bheil thu airson leantainn air %n neach?"],
